//! The typed, server-owned state of a space and the rules that change it: the back's RaiseHandManager,
//! ProximityPollManager and ProximityQAManager.
//!
//! The types come from the zod schema (libs/shared-utils/src/SpaceState/SpaceState.ts), generated by
//! tools/gen-space-state.sh: a string the schema bounds is a newtype that cannot be built out of bounds. The
//! generator does not bound arrays and integers, so those checks are written here. Lengths are counted in
//! characters, zod counts UTF-16 units: a text made of emoji may be up to twice as long as on the TypeScript server.

mod generated;

use std::num::NonZeroU64;

pub use generated::*;

use crate::space::{FilterType, SpaceUser};

/// PROXIMITY_POLL_MAX_ANSWERS.
pub const POLL_MAX_ANSWERS: usize = 20;
/// PROXIMITY_POLL_SENDER_NAME_MAX_LENGTH and PROXIMITY_QA_SENDER_NAME_MAX_LENGTH.
const SENDER_NAME_MAX: usize = 256;

/// `emptySpaceState()`.
pub fn empty() -> SpaceState {
    SpaceState {
        kind: None,
        raised_hands: Vec::new(),
        floor_holders: Vec::new(),
        recording: RecordingState {
            recording: false,
            recorder: None,
            status: RecordingStatus::Idle,
        },
        polls: Default::default(),
        questions: Default::default(),
    }
}

/// What a client may ask of the state (SpaceStateQuery). Recording is refused before it gets here.
#[derive(Debug, Clone)]
pub enum StateQuery {
    RaiseHand(bool),
    LowerHand(String),
    GiveFloor(String),
    RevokeFloor(String),
    CreatePoll {
        question: String,
        kind: String,
        answers: Vec<String>,
        max_selections: i32,
    },
    VotePoll {
        poll_id: String,
        answer_ids: Vec<String>,
    },
    ClosePoll {
        poll_id: String,
        closing_message: Option<String>,
    },
    DeletePoll(String),
    AskQuestion(String),
    UpvoteQuestion {
        question_id: String,
        upvoted: bool,
    },
    AnswerQuestion(String),
    DeleteQuestion(String),
    SetKind(String),
}

/// What a query sees of its space.
pub(crate) struct Ctx<'a> {
    pub sender: &'a SpaceUser,
    pub filter: FilterType,
    pub members: &'a [SpaceUser],
    pub now: i64,
    pub new_id: &'a mut dyn FnMut() -> String,
}

/// The identity polls and questions are attributed to: the uuid, or the spaceUserId when there is none.
pub fn voter_id(u: &SpaceUser) -> &str {
    if u.uuid.is_empty() { &u.space_user_id } else { &u.uuid }
}

fn is_admin(u: &SpaceUser) -> bool {
    u.tags.iter().any(|t| t == "admin")
}

fn checked<T: TryFrom<String, Error = error::ConversionError>>(what: &str, value: String) -> Result<T, String> {
    T::try_from(value).map_err(|e| format!("{what}: {e}"))
}

fn sender_name(name: &str) -> String {
    name.chars().take(SENDER_NAME_MAX).collect()
}

/// Applies a query. On error the state may be half changed: the caller restores its copy.
pub(crate) fn apply(state: &mut SpaceState, ctx: &mut Ctx<'_>, query: StateQuery) -> Result<(), String> {
    let sender = ctx.sender;
    match query {
        // ------------------------------------------------------------ raised hands and floor
        StateQuery::RaiseHand(raised) => {
            if !raised {
                state.raised_hands.retain(|e| *e.space_user_id != sender.space_user_id);
            } else if !state.raised_hands.iter().any(|e| *e.space_user_id == sender.space_user_id) {
                state.raised_hands.push(RaisedHandEntry {
                    space_user_id: checked("spaceUserId", sender.space_user_id.clone())?,
                    name: sender.name.clone(),
                    at: ctx.now,
                });
            }
        }
        StateQuery::LowerHand(target) => {
            can_moderate(state, ctx)?;
            state.raised_hands.retain(|e| *e.space_user_id != target);
        }
        StateQuery::GiveFloor(target) => {
            can_moderate(state, ctx)?;
            let Some(user) = ctx.members.iter().find(|m| m.space_user_id == target) else {
                return Err(format!("User {target} is not in the space"));
            };
            state.raised_hands.retain(|e| *e.space_user_id != target);
            // In a proximity (ALL_USERS) space everyone already speaks: there is no floor to hold.
            if ctx.filter != FilterType::AllUsers && !state.floor_holders.iter().any(|e| *e.space_user_id == target) {
                state.floor_holders.push(FloorHolderEntry {
                    space_user_id: checked("spaceUserId", target)?,
                    name: user.name.clone(),
                });
            }
        }
        StateQuery::RevokeFloor(target) => {
            // A floor holder may always hand the floor back.
            if target != sender.space_user_id {
                can_moderate(state, ctx)?;
            }
            state.floor_holders.retain(|e| *e.space_user_id != target);
        }

        // ------------------------------------------------------------ polls
        StateQuery::CreatePoll {
            question,
            kind,
            answers,
            max_selections,
        } => {
            if !(2..=POLL_MAX_ANSWERS).contains(&answers.len()) {
                return Err(format!("A poll needs 2 to {POLL_MAX_ANSWERS} answers"));
            }
            let max = usize::try_from(max_selections).unwrap_or(0);
            if !(1..=POLL_MAX_ANSWERS).contains(&max) {
                return Err(format!("maxSelections must be between 1 and {POLL_MAX_ANSWERS}"));
            }
            if max > answers.len() {
                return Err("A poll cannot allow more selections than it has answers".into());
            }
            let answers = answers
                .into_iter()
                .map(|text| {
                    Ok(ProximityPollAnswer {
                        id: checked("answer id", (ctx.new_id)())?,
                        text: checked("answer", text)?,
                    })
                })
                .collect::<Result<Vec<_>, String>>()?;
            let poll = ProximityPoll {
                id: checked("id", (ctx.new_id)())?,
                question: checked("question", question)?,
                kind: kind.parse().map_err(|e| format!("kind: {e}"))?,
                answers,
                max_selections: NonZeroU64::new(max as u64).expect("checked above"),
                sender_id: checked("senderId", voter_id(sender).to_owned())?,
                sender_name: Some(checked("senderName", sender_name(&sender.name))?),
                created_at: ctx.now,
                end: None,
                votes: Default::default(),
            };
            state.polls.insert(poll.id.to_string(), poll);
        }
        StateQuery::VotePoll { poll_id, answer_ids } => {
            let poll = poll(state, &poll_id)?;
            if poll.end.is_some() {
                return Err("This poll is closed".into());
            }
            if answer_ids.len() as u64 > poll.max_selections.get() {
                return Err("Poll vote selects more answers than the poll allows".into());
            }
            if answer_ids.iter().any(|a| !poll.answers.iter().any(|p| *p.id == *a)) {
                return Err("Poll vote references answers that do not belong to the poll".into());
            }
            let voter = voter_id(sender).to_owned();
            if answer_ids.is_empty() {
                poll.votes.remove(&voter);
            } else {
                let answer_ids = answer_ids
                    .into_iter()
                    .map(|a| checked("answer id", a))
                    .collect::<Result<_, _>>()?;
                poll.votes.insert(
                    voter,
                    ProximityPollVote {
                        answer_ids,
                        updated_at: ctx.now,
                    },
                );
            }
        }
        StateQuery::ClosePoll { poll_id, closing_message } => {
            let poll = poll(state, &poll_id)?;
            if *poll.sender_id != voter_id(sender) {
                return Err("Only poll creators can close a poll".into());
            }
            if poll.end.is_some() {
                return Ok(());
            }
            let closing_message = closing_message
                .map(ProximityPollEndClosingMessage::try_from)
                .transpose()
                .map_err(|_| "The closing message is too long")?;
            poll.end = Some(ProximityPollEnd {
                closing_message,
                closed_at: ctx.now,
            });
        }
        StateQuery::DeletePoll(poll_id) => {
            if *poll(state, &poll_id)?.sender_id != voter_id(sender) {
                return Err("Only poll creators can delete a poll".into());
            }
            state.polls.remove(&poll_id);
        }

        // ------------------------------------------------------------ questions
        StateQuery::AskQuestion(body) => {
            let question = ProximityQuestion {
                id: checked("id", (ctx.new_id)())?,
                body: checked("body", body)?,
                sender_id: checked("senderId", voter_id(sender).to_owned())?,
                sender_name: Some(checked("senderName", sender_name(&sender.name))?),
                created_at: ctx.now,
                answer: None,
                upvotes: Default::default(),
            };
            state.questions.insert(question.id.to_string(), question);
        }
        StateQuery::UpvoteQuestion { question_id, upvoted } => {
            let question = question(state, &question_id)?;
            let voter = voter_id(sender);
            if *question.sender_id == voter {
                return Err("Question authors cannot upvote their own question".into());
            }
            if question.answer.is_some() {
                return Err("This question has already been answered".into());
            }
            if upvoted {
                question.upvotes.entry(voter.to_owned()).or_insert(ctx.now);
            } else {
                question.upvotes.remove(voter);
            }
        }
        StateQuery::AnswerQuestion(question_id) => {
            if !is_admin(sender) && !sender.megaphone_state {
                return Err("Only moderators can mark a question as answered".into());
            }
            let question = question(state, &question_id)?;
            if question.answer.is_none() {
                question.answer = Some(ProximityQuestionAnswer {
                    moderator_id: checked("moderatorId", voter_id(sender).to_owned())?,
                    answered_at: ctx.now,
                });
            }
        }
        StateQuery::DeleteQuestion(question_id) => {
            if *question(state, &question_id)?.sender_id != voter_id(sender) && !is_admin(sender) {
                return Err("Only question authors or admins can delete a question".into());
            }
            state.questions.remove(&question_id);
        }

        StateQuery::SetKind(kind) => {
            state.kind = Some(kind.parse().map_err(|_| "Invalid space kind")?);
        }
    }
    Ok(())
}

/// Admins always moderate. In a proximity (ALL_USERS) space anyone may. In a broadcast space only speakers may,
/// and not a guest who was only given the floor.
fn can_moderate(state: &SpaceState, ctx: &Ctx<'_>) -> Result<(), String> {
    let sender = ctx.sender;
    if is_admin(sender) || ctx.filter == FilterType::AllUsers {
        return Ok(());
    }
    let promoted_guest = state.floor_holders.iter().any(|e| *e.space_user_id == sender.space_user_id);
    if sender.megaphone_state && !promoted_guest {
        return Ok(());
    }
    Err("Only a speaker or an admin can manage the floor".into())
}

fn poll<'a>(state: &'a mut SpaceState, id: &str) -> Result<&'a mut ProximityPoll, String> {
    state
        .polls
        .get_mut(id)
        .ok_or_else(|| format!("Poll {id} does not exist in this space"))
}

fn question<'a>(state: &'a mut SpaceState, id: &str) -> Result<&'a mut ProximityQuestion, String> {
    state
        .questions
        .get_mut(id)
        .ok_or_else(|| format!("Question {id} does not exist in this space"))
}

/// A member left: no ghost entry in the queue, nor in the host's "take back" panel.
pub(crate) fn forget(state: &mut SpaceState, id: &str) {
    state.raised_hands.retain(|e| *e.space_user_id != id);
    state.floor_holders.retain(|e| *e.space_user_id != id);
}

/// A floor holder who stops streaming no longer holds the floor.
pub(crate) fn stopped_streaming(state: &mut SpaceState, id: &str) {
    state.floor_holders.retain(|e| *e.space_user_id != id);
}
